namespace Phobos.Domain;

public enum ImageOrigin { Generated, Web }

/// <summary>Where an image comes from: generated by AI, or found on the web under a licence that allows it.</summary>
public sealed record ImageCredit
{
    private ImageCredit(ImageOrigin origin, string? author, string? license, Uri? source)
    {
        Origin = origin;
        Author = author;
        License = license;
        Source = source;
    }

    public ImageOrigin Origin { get; }
    public string? Author { get; }
    public string? License { get; }
    public Uri? Source { get; }

    public static ImageCredit Generated { get; } = new(ImageOrigin.Generated, null, null, null);

    /// <param name="author">Null or blank when unknown (public domain, for instance).</param>
    public static ImageCredit Licensed(string license, Uri source, string? author)
    {
        if (string.IsNullOrWhiteSpace(license)) throw new DomainRuleException("An image found on the web needs a licence.");
        if (!source.IsAbsoluteUri || (source.Scheme != Uri.UriSchemeHttps && source.Scheme != Uri.UriSchemeHttp))
            throw new DomainRuleException($"'{source}' is not the web address the image comes from.");
        return new ImageCredit(ImageOrigin.Web, string.IsNullOrWhiteSpace(author) ? null : author, license, source);
    }
}
